import{_ as e,o as t,c as i,a5 as r}from"./chunks/framework.DrDMl0tG.js";const n="/assets/rayrai_quality_lighting.DXfAADe4.png",g=JSON.parse('{"title":"Rayrai Example: Quality Lighting and FXAA","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_quality_lighting.md","filePath":"sections/examples/rayrai/rayrai_quality_lighting.md"}'),l={name:"sections/examples/rayrai/rayrai_quality_lighting.md"};function s(o,a,d,h,c,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="rayrai-example-quality-lighting-and-fxaa" tabindex="-1">Rayrai Example: Quality Lighting and FXAA <a class="header-anchor" href="#rayrai-example-quality-lighting-and-fxaa" aria-label="Permalink to &quot;Rayrai Example: Quality Lighting and FXAA&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Demonstrates rayrai&#39;s high-fidelity viewer controls with a reflective ground, FXAA, depth of field, and multiple additional light types. The main directional light owns the cheapest shadow map, while point lights use cube shadow maps and directional, spot, and area-style lights use 2D shadow maps when they are selected into the shadow budget. The example is intended for inspection and presentation rather than maximum batch data-generation throughput.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+n+'" alt="rayrai_quality_lighting example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_quality_lighting</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_quality_lighting</span></span></code></pre></div><p>On Windows, run <code>rayrai_quality_lighting.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Enables the <code>Ultra</code> render-quality preset and explicitly keeps <code>fxaaEnabled</code>, <code>depthOfFieldEnabled</code>, and <code>reflectiveGround</code> on, with a 5 m focus distance, a broad focus range, and a conservative blur radius.</li><li>Adds one point light, one spotlight with inner/outer cone falloff, and one area-light approximation.</li><li>Demonstrates the extra-light path used by authored visual scenes. Fast/Balanced presets keep the default one-light path inexpensive; High/Ultra can spend more budget on additional lights, shadow maps, reflection probes, and postprocessing.</li><li>Uses the real planar reflection path on the ground material instead of placing duplicate reflection geometry.</li></ul>',13)])])}const m=e(l,[["render",s]]);export{g as __pageData,m as default};
